-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 13
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 13 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 13', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 13 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-13.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Defina ponto de atrito (pain point) com as suas palavras.', 0.2, 'Ponto de atrito (pain point) é um momento da jornada em que o usuário sente dúvida, lentidão ou frustração e deixa de avançar para a meta. Pode ser descrito com outras palavras, desde que a ideia de obstáculo na jornada apareça.', 'Nota cheia: define ponto de atrito como momento de dúvida, lentidão ou frustração que impede ou dificulta a conclusão da meta, com as próprias palavras. Metade: identifica o atrito como problema na jornada, mas a definição é vaga ou falta a ideia de impedimento. Zero: em branco, define por outro conceito (ex.: velocidade de programação, beleza visual) ou copia sem adaptar.'),
      (v_atividade, 1, 2, 'Dê um exemplo de momento de dúvida, lentidão ou frustração nessa jornada.', 0.4, 'No serviço de agendamento, o atrito aparece na escolha da data: o usuário não sabe quais dias estão livres, não entende o formato pedido ou não sabe se a escolha foi confirmada. Qualquer exemplo que relate dúvida, lentidão ou frustração nessa etapa atende.', 'Nota cheia: dá um exemplo concreto de dúvida, lentidão ou frustração ligado à escolha da data (ou outra etapa da jornada descrita), explicando o motivo. Metade: dá exemplo genérico, sem ligação clara com a etapa de agendamento. Zero: em branco, exemplo fora da jornada (ex.: problema de servidor sem relação com a etapa) ou copiado.'),
      (v_atividade, 1, 3, 'Justifique por que mapear esse atrito antes do desenho da tela evita retrabalho.', 0.4, 'Mapear o atrito antes de desenhar a tela evita retrabalho porque mostra onde a tela precisa resolver um problema real do usuário, e não uma suposição do designer. Assim a tela já nasce corrigindo a barreira, sem refazer depois.', 'Nota cheia: justifica que o mapeamento aponta problemas reais antes do desenho, o que reduz refações e retrabalho, com as próprias palavras. Metade: diz que o mapeamento ajuda, sem explicar a relação com o retrabalho. Zero: em branco, resposta que não relaciona o atrito ao desenho da tela ou copiada.'),
      (v_atividade, 2, 1, 'Escreva a definição de usabilidade da norma com as suas palavras.', 0.2, 'Segundo a ISO 9241-11, usabilidade é a capacidade de um sistema permitir que usuários específicos alcancem metas com eficácia, eficiência e satisfação em um contexto determinado.', 'Nota cheia: define usabilidade como capacidade de o sistema permitir que usuários atinjam metas com eficácia, eficiência e satisfação, em certo contexto. Metade: cita a norma e os três critérios, mas a definição fica incompleta (ex.: não menciona a meta ou o contexto). Zero: em branco, define usabilidade como aparência, beleza ou cores, ou copia sem adaptar.'),
      (v_atividade, 2, 2, 'Explique o que significa o usuário alcançar metas com eficácia e eficiência.', 0.4, 'Alcançar metas com eficácia é concluir a tarefa de forma completa e sem erros fatais; com eficiência, fazer isso gastando o menor tempo, cliques e esforço possíveis.', 'Nota cheia: explica eficácia como concluir a meta completa e com sucesso, e eficiência como usar o mínimo de tempo, cliques e esforço, com as próprias palavras. Metade: explica apenas um dos dois conceitos, ou os define de forma vaga. Zero: em branco, define os termos de forma errada (ex.: eficácia como velocidade) ou copia sem adaptar.'),
      (v_atividade, 2, 3, 'Explique, com um exemplo, por que a satisfação não depende só da aparência.', 0.4, 'A satisfação é a sensação de conforto, segurança e ausência de frustração ao usar o sistema. Um exemplo: uma tela bonita, mas com um botão que não deixa claro o que acontece, pode gerar desconfiança e frustração, mesmo com cores agradáveis.', 'Nota cheia: explica satisfação como conforto, confiança e ausência de frustração, e dá um exemplo em que a aparência sozinha não garante a sensação positiva. Metade: explica satisfação, mas o exemplo é fraco ou não mostra que a aparência não basta. Zero: em branco, afirma que a satisfação depende só da beleza ou copia sem adaptar.'),
      (v_atividade, 3, 1, 'Nomeie os três pilares da usabilidade.', 0.2, 'Os três pilares da usabilidade são eficácia, eficiência e satisfação.', 'Nota cheia: nomeia eficácia, eficiência e satisfação. Metade: nomeia dois dos três pilares. Zero: em branco ou nomeia outros critérios que não são pilares da norma (ex.: beleza, cores, preço).'),
      (v_atividade, 3, 2, 'Descreva a eficácia e a eficiência em uma frase cada.', 0.4, 'Eficácia é o usuário conseguir completar o formulário inteiro, sem bloqueios por bugs ou instruções truncadas. Eficiência é fazer isso com poucos cliques, pouco tempo e pouco esforço mental.', 'Nota cheia: descreve eficácia como concluir a tarefa completa sem bloqueios e eficiência como mínimo de tempo, cliques e esforço, cada um em uma frase, aplicados ao formulário. Metade: descreve os dois conceitos, mas sem ligação com o formulário, ou só um deles. Zero: em branco, define os termos de forma errada ou copia sem adaptar.'),
      (v_atividade, 3, 3, 'Descreva como a satisfação se percebe ao final do cadastro.', 0.4, 'Ao final do cadastro, a satisfação se percebe pela sensação de conforto, pela ausência de ansiedade (por exemplo, não ficar em dúvida se o cadastro foi concluído) e pela vontade de usar o sistema de novo.', 'Nota cheia: descreve a satisfação no fim do cadastro como conforto, confiança e vontade de voltar, sem ansiedade, com as próprias palavras. Metade: descreve a satisfação de forma genérica, sem ligar ao fim do cadastro. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 4, 1, 'Explique, com as suas palavras, o que significa uma interface amigável.', 0.2, 'Interface amigável é aquela que acolhe a pessoa usuária: não presume conhecimento técnico avançado, não pune pequenas distrações e dialoga com calma, clareza e paciência.', 'Nota cheia: explica que a interface amigável acolhe o usuário, não exige conhecimento técnico avançado e conversa com calma e clareza, com as próprias palavras. Metade: diz apenas que ela é "fácil de usar", sem os outros traços. Zero: em branco, define como interface bonita ou copia sem adaptar.'),
      (v_atividade, 4, 2, 'Cite os três pilares do friendly (acolhedora, clara e paciente).', 0.4, 'Os três pilares do friendly são: acolhedora (linguagem simples e visual limpo que não assusta iniciantes), clara (cada botão e termo revela exatamente o que acontecerá) e paciente (tolera erros com mensagens construtivas e permite desfazer passos).', 'Nota cheia: cita os três pilares (acolhedora, clara e paciente) e explica cada um em uma frase, com as próprias palavras. Metade: cita dois dos três pilares, ou cita os três sem explicar. Zero: em branco, cita outros pilares ou copia sem adaptar.'),
      (v_atividade, 4, 3, 'Dê um exemplo de como o sistema pode ser paciente com o erro do usuário.', 0.4, 'O sistema é paciente com o erro do usuário quando mostra uma mensagem construtiva (por exemplo, "O e-mail precisa conter um @") e oferece a opção de desfazer a ação, como um botão "Desfazer" ou "Voltar" depois de um cancelamento.', 'Nota cheia: dá um exemplo concreto de paciência com o erro (mensagem construtiva, desfazer, confirmação de volta) e explica por que ele tolera o erro. Metade: exemplo genérico ("ajudar o usuário") sem mostrar como a interface age. Zero: em branco, exemplo que pune o usuário (ex.: bloquear sem explicar) ou copiado.'),
      (v_atividade, 5, 1, 'Defina interface intuitiva com as suas palavras.', 0.2, 'Interface intuitiva é aquela em que o usuário consegue deduzir a ação correta sem manual, a partir do que já aprendeu no mundo real ou em outros aplicativos; seu funcionamento é óbvio quase à primeira vista.', 'Nota cheia: define interface intuitiva como aquela que o usuário opera com a ação deduzida, sem manual, com as próprias palavras. Metade: define como "fácil", sem falar em dedução ou sem manual. Zero: em branco, define como bonita ou copia sem adaptar.'),
      (v_atividade, 5, 2, 'Explique o papel do que o usuário já aprendeu no mundo real ou em outros aplicativos.', 0.4, 'O usuário usa o que já conhece de outros aplicativos e da vida real, como o ícone de carrinho ou o botão de confirmar, para deduzir o que fazer. Essa bagagem reduz a necessidade de aprender tudo do zero.', 'Nota cheia: explica que o conhecimento anterior (outros apps, vida real) permite deduzir a ação correta, reduzindo o aprendizado. Metade: menciona a experiência anterior sem explicar como ela ajuda. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 5, 3, 'Explique por que a necessidade de ler um manual indica falha de design.', 0.4, 'Precisar de um manual para agendar uma consulta mostra que o design falhou no teste de intuitividade, porque a tela deveria comunicar o caminho sem instruções externas. A falha está na interface, não no usuário.', 'Nota cheia: explica que a necessidade de manual indica falha de design, pois a tela deveria ser óbvia, com as próprias palavras. Metade: diz que o manual "não é bom", sem ligar à falha de design. Zero: em branco, culpa o usuário ou copiado.'),
      (v_atividade, 6, 1, 'Explique o que é um modelo mental do usuário.', 0.2, 'O modelo mental é a ideia que o usuário já tem de como um sistema funciona, formada por experiências anteriores e expectativas. Quando a interface combina com esse modelo, o usuário age sem hesitar.', 'Nota cheia: define modelo mental como a representação que o usuário tem do funcionamento do sistema, formada pela experiência e pelas expectativas, com as próprias palavras. Metade: define de forma vaga ("o que o usuário pensa"), sem ligar a expectativas ou experiência. Zero: em branco ou define de forma errada.'),
      (v_atividade, 6, 2, 'Explique por que o ícone de carrinho e o de lupa são úteis quando seguem convenções conhecidas.', 0.4, 'Carrinho e lupa são úteis porque seguem convenções conhecidas: o usuário já sabe que o carrinho guarda os itens da compra e que a lupa indica busca. Por isso ele encontra essas funções sem procurar.', 'Nota cheia: explica que as convenções conhecidas permitem reconhecer a função dos ícones sem aprendizado, e aplica ao carrinho e à lupa. Metade: diz que os ícones são úteis, sem explicar a convenção. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 6, 3, 'Diga o risco de criar um ícone novo sem convenção para uma ação comum.', 0.4, 'Criar um ícone novo para uma ação comum sem convenção obriga o usuário a adivinhar o significado, aumenta a dúvida e pode levar a cliques errados ou à desistência.', 'Nota cheia: aponta o risco de confusão, adivinhação e erro ao usar um símbolo sem convenção para ação comum, com as próprias palavras. Metade: diz que é "ruim", sem explicar o risco. Zero: em branco, defende o ícone novo ou copiado.'),
      (v_atividade, 7, 1, 'Descreva a fase de primeiro contato do usuário.', 0.2, 'No primeiro contato, o usuário tateia os botões e tenta reconhecer padrões da interface, ainda sem domínio da tela.', 'Nota cheia: descreve o primeiro contato como fase de exploração e reconhecimento de padrões pelo usuário, com as próprias palavras. Metade: descreve de forma genérica ("o usuário começa a usar"). Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 7, 2, 'Explique como o feedback claro reduz o esforço mental na compreensão rápida.', 0.4, 'O feedback claro informa o que aconteceu após cada ação; assim o usuário não precisa adivinhar nem lembrar o estado do sistema, e o esforço mental cai, acelerando a compreensão.', 'Nota cheia: explica que o feedback claro reduz a dúvida sobre o resultado da ação e diminui o esforço mental, acelerando a compreensão. Metade: diz que o feedback "ajuda", sem relacionar ao esforço mental. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 7, 3, 'Explique o que caracteriza o domínio total e por que ele depende de uma interface intuitiva.', 0.4, 'O domínio total é quando as ações se tornam fluidas e automáticas. Ele depende de uma interface intuitiva porque, se a tela é óbvia e consistente, o usuário memoriza os padrões e executa sem pensar em cada passo.', 'Nota cheia: caracteriza o domínio total como ações fluidas e automáticas e liga esse estado à intuitividade (padrões consistentes e óbvios), com as próprias palavras. Metade: descreve o domínio sem ligar à intuitividade. Zero: em branco, define o domínio de outra forma ou copia sem adaptar.'),
      (v_atividade, 8, 1, 'Descreva o problema do campo com código abstrato.', 0.2, 'O campo de texto pede um código abstrato (como "M1") que o usuário não conhece. Ele precisa adivinhar, lembrar ou procurar fora da tela, o que gera erro e desistência.', 'Nota cheia: descreve que o código abstrato exige do usuário um conhecimento que ele não tem, gerando erro ou esforço, com as próprias palavras. Metade: diz que o campo "é confuso", sem explicar o código. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 8, 2, 'Explique a proposta de substituir o código por uma lista com nomes legíveis.', 0.4, 'Trocar o código por uma lista com nomes legíveis (por exemplo, "Clínica Geral") faz o usuário escolher pelo que conhece, sem decorar siglas. O código continua existindo por trás, oculto da pessoa usuária.', 'Nota cheia: explica que a lista com nomes legíveis elimina a necessidade de decorar o código e reduz o esforço, com as próprias palavras. Metade: propõe a lista sem explicar o efeito no esforço. Zero: em branco, propõe manter o código ou copiado.'),
      (v_atividade, 8, 3, 'Explique como a busca digitável ajuda o usuário a chegar à opção correta.', 0.4, 'A busca digitável ajuda porque o usuário digita parte do nome (por exemplo, "clí") e a lista filtra as opções. Assim ele chega à especialidade certa em poucos passos, sem rolar uma lista longa.', 'Nota cheia: explica que a busca filtra as opções a partir do que o usuário digita, reduzindo o esforço para achar a opção certa, com as próprias palavras. Metade: diz que a busca "ajuda", sem explicar o filtro. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 9, 1, 'Explique o que o sistema deve sempre informar ao usuário.', 0.2, 'O sistema deve sempre informar o usuário sobre o que está acontecendo no momento, por meio de retornos visuais rápidos e apropriados.', 'Nota cheia: diz que o sistema deve manter o usuário informado sobre o que está acontecendo, com retorno visual rápido e apropriado, com as próprias palavras. Metade: diz apenas "mostrar que está funcionando", sem o aspecto de informar a situação. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 9, 2, 'Diferencie feedback de progresso de feedback de confirmação.', 0.4, 'Feedback de progresso mostra que o sistema está trabalhando no pedido (spinner, barra de progresso). Feedback de confirmação mostra que a ação terminou com êxito (caixa verde, notificação de "salvo").', 'Nota cheia: diferencia progresso (sistema em andamento) de confirmação (ação concluída), com exemplos ou com as próprias palavras. Metade: diferencia os dois, mas sem clareza sobre o momento de cada um. Zero: em branco, trata os dois como iguais ou copia sem adaptar.'),
      (v_atividade, 9, 3, 'Proponha um retorno visual para o clique em "Enviar" e explique como ele evita cliques duplicados.', 0.4, 'Ao clicar em "Enviar", a tela deve mostrar imediatamente um indicador de progresso (spinner ou desabilitar o botão e mostrar "Enviando…") e, ao final, uma confirmação. Assim o usuário sabe que o clique foi registrado e não clica de novo, evitando pedidos duplicados.', 'Nota cheia: propõe retorno visual imediato no clique (progresso e/ou botão desabilitado) e confirmação ao final, e explica como isso evita o clique duplicado. Metade: propõe um retorno visual, sem explicar como evita o duplicado. Zero: em branco, proposta que não dá retorno visual ou copiada.'),
      (v_atividade, 10, 1, 'Explique por que impedir o erro é melhor do que mostrar uma mensagem de erro.', 0.2, 'Impedir o erro é melhor porque o usuário não chega a cometê-lo, o que economiza tempo e evita frustração. Uma mensagem de erro só aparece depois que o problema já aconteceu.', 'Nota cheia: explica que prevenir evita o erro antes de ocorrer, enquanto a mensagem só reage depois, com as próprias palavras. Metade: diz que prevenir "é melhor", sem explicar a diferença no tempo do erro. Zero: em branco, defende apenas a mensagem de erro ou copia sem adaptar.'),
      (v_atividade, 10, 2, 'Descreva uma máscara de digitação e o problema que ela evita.', 0.4, 'A máscara de digitação formata o CPF (000.000.000-00) e o telefone enquanto o usuário digita. Ela evita dados em formatos inconsistentes, que quebram validações e geram retrabalho no cadastro.', 'Nota cheia: descreve a máscara como formatação automática durante a digitação e explica o problema evitado (formato inconsistente e erro de validação). Metade: descreve a máscara sem o problema que ela evita. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 10, 3, 'Descreva a confirmação antes de excluir dados permanentes e por que ela é necessária.', 0.4, 'A confirmação antes de excluir dados permanentes (pergunta "Tem certeza?") é necessária porque um clique acidental apagaria informações que não podem ser recuperadas. Ela dá ao usuário uma chance de revisar a ação antes do dano.', 'Nota cheia: descreve a confirmação antes da exclusão e explica que ela evita perda irreversível por clique acidental, com as próprias palavras. Metade: propõe a confirmação sem explicar o motivo. Zero: em branco, propõe excluir sem confirmação ou copia sem adaptar.'),
      (v_atividade, 11, 1, 'Aponte por que a mensagem atual é destrutiva.', 0.2, 'A mensagem "Erro 404: Requisição inválida de dados." é destrutiva porque culpa o usuário, usa jargão técnico que ele não entende e não indica nenhuma solução prática para continuar.', 'Nota cheia: aponta pelo menos dois problemas da mensagem (culpa o usuário, jargão, sem solução), com as próprias palavras. Metade: aponta um problema só. Zero: em branco, elogia a mensagem ou copia sem adaptar.'),
      (v_atividade, 11, 2, 'Escreva uma mensagem construtiva para o mesmo erro.', 0.4, 'Uma versão construtiva é, por exemplo: "O e-mail precisa conter um @. Exemplo: nome@email.com". A mensagem explica o que faltou e mostra um modelo concreto.', 'Nota cheia: escreve mensagem educada, clara, sem jargão, que indica o que faltou e dá um exemplo do formato correto. Metade: escreve mensagem clara, mas sem exemplo ou ainda com algum termo técnico. Zero: em branco, mensagem que ainda culpa o usuário ou usa código técnico, ou copiada.'),
      (v_atividade, 11, 3, 'Explique quais características da sua mensagem a tornam construtiva.', 0.4, 'A mensagem construtiva usa linguagem educada e compreensível, indica o campo com problema, dá um exemplo do formato correto e foca o cursor no ponto a corrigir, o que orienta a correção sem obrigar a pessoa a adivinhar.', 'Nota cheia: cita pelo menos duas características (linguagem simples, indicação do campo, exemplo, foco no campo) e explica como elas ajudam a corrigir o erro, com as próprias palavras. Metade: cita uma característica, sem explicar o efeito. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 12, 1, 'Diga por que o código hexadecimal não ajuda o usuário.', 0.2, 'O código hexadecimal interno do banco de dados não ajuda o usuário, porque é um dado técnico que ele não entende e não diz o que fazer para resolver o problema.', 'Nota cheia: explica que o código é técnico, sem significado para o usuário e sem orientação de correção, com as próprias palavras. Metade: diz que o código "é confuso", sem explicar a falta de orientação. Zero: em branco, defende o código ou copia sem adaptar.'),
      (v_atividade, 12, 2, 'Diga por que bloquear o formulário inteiro prejudica a experiência.', 0.4, 'Bloquear o formulário inteiro prejudica porque o usuário não sabe qual campo errou e precisa refazer todo o preenchimento, o que gera frustração e desistência.', 'Nota cheia: explica que o bloqueio total não indica o campo com erro e obriga a refazer o preenchimento, com as próprias palavras. Metade: diz que o bloqueio "atrapalha", sem explicar o motivo. Zero: em branco, defende o bloqueio ou copia sem adaptar.'),
      (v_atividade, 12, 3, 'Proponha como a mensagem deve indicar o campo e orientar a correção.', 0.4, 'A mensagem deve indicar o campo com erro (destacando-o e focando o cursor nele) e orientar a correção, com um exemplo do formato esperado, por exemplo: "O cartão precisa ter 16 números. Confira o campo Número do cartão."', 'Nota cheia: propõe que a mensagem aponte o campo exato e oriente a correção de forma prática, com as próprias palavras. Metade: propõe apontar o campo, sem orientar a correção, ou o contrário. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 13, 1, 'Escreva a pergunta que um botão deve responder na mente do usuário.', 0.2, 'A pergunta que o botão deve responder na mente do usuário é: "O que acontecerá imediatamente se eu tocar aqui?".', 'Nota cheia: escreve a pergunta sobre o resultado imediato da ação, ou equivalente com as próprias palavras. Metade: escreve pergunta vaga, sem ligar ao resultado da ação. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 13, 2, 'Avalie "Executar" e "Processar" quanto à clareza do que vai acontecer.', 0.4, '"Executar" e "Processar" são ruins porque não dizem o que vai acontecer (executar o quê? processar o quê?). Os dois botões são idênticos e cinzas, então o usuário não distingue a ação principal da secundária.', 'Nota cheia: avalia os dois botões como pouco claros, por não indicarem o resultado da ação, e aponta que são idênticos (sem destaque da ação principal). Metade: avalia só o texto, ou só a aparência, sem os dois aspectos. Zero: em branco, avalia como claros ou copia sem adaptar.'),
      (v_atividade, 13, 3, 'Proponha um rótulo mais claro para a ação principal e explique a escolha.', 0.4, 'Um rótulo mais claro é "Confirmar Agendamento", que diz exatamente a ação e o resultado. O botão deve ter contraste forte (cor de destaque), porque a ação primária precisa ser a mais visível da tela.', 'Nota cheia: propõe rótulo com verbo de ação e resultado claro (ex.: "Confirmar Agendamento") e justifica pelo que o usuário entende e pelo destaque visual. Metade: propõe rótulo melhor, sem justificativa. Zero: em branco, rótulo ainda vago (ex.: "Enviar", "OK") ou copiado.'),
      (v_atividade, 14, 1, 'Explique por que o jargão técnico prejudica o usuário comum.', 0.2, 'O jargão técnico prejudica o usuário comum porque ele não entende o que está escrito, sente que não é capaz de usar o sistema e pode desistir da ação.', 'Nota cheia: explica que o jargão não é compreendido pelo usuário comum e gera insegurança ou desistência, com as próprias palavras. Metade: diz que o jargão "confunde", sem o efeito no usuário. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 14, 2, 'Reescreva o texto usando a linguagem que o usuário usa no dia a dia.', 0.4, '"Entrar com impressão digital". A reescrita usa a linguagem do dia a dia, descrevendo o que o usuário vai fazer.', 'Nota cheia: reescreve com palavras simples e cotidianas que descrevem a ação (ex.: "Entrar com impressão digital"). Metade: reescreve com linguagem mais simples, mas ainda com termo técnico. Zero: em branco, mantém o jargão ou copia o texto original.'),
      (v_atividade, 14, 3, 'Explique como a linguagem simples reduz a sensação de incapacidade técnica.', 0.4, 'A linguagem simples reduz a sensação de incapacidade técnica porque o usuário entende o que faz e percebe que o sistema foi feito para ele, o que aumenta a segurança e a confiança para continuar.', 'Nota cheia: explica que a linguagem simples dá segurança e reduz a sensação de incapacidade, com as próprias palavras. Metade: diz que a linguagem "ajuda", sem explicar a sensação de incapacidade. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 15, 1, 'Diga por que orientações críticas não devem ficar em botões de ajuda minúsculos.', 0.2, 'Orientações críticas em botões de ajuda minúsculos são ruins porque o usuário não as vê, e as descobre só depois de errar. Informações necessárias para concluir a tarefa devem estar visíveis no momento em que são usadas.', 'Nota cheia: explica que a orientação escondida passa despercebida e só aparece depois do erro, com as próprias palavras. Metade: diz que o botão "é pequeno", sem falar em visibilidade no momento certo. Zero: em branco, defende o botão escondido ou copia sem adaptar.'),
      (v_atividade, 15, 2, 'Explique o que é rótulo permanente e por que ele deve ficar visível após o preenchimento.', 0.4, 'Rótulo permanente é o nome do campo que fica visível acima do campo mesmo depois de preenchido. Ele deve permanecer porque, sem ele, o usuário esquece o que foi pedido naquele campo (por exemplo, ao ver só o número digitado).', 'Nota cheia: define rótulo permanente como nome visível do campo mesmo após o preenchimento e explica por que ele evita a dúvida sobre o campo, com as próprias palavras. Metade: define rótulo, sem explicar por que deve ficar visível. Zero: em branco, confunde com placeholder que some ou copia sem adaptar.'),
      (v_atividade, 15, 3, 'Explique por que as regras de senha devem aparecer antes da digitação.', 0.4, 'As regras de senha devem aparecer antes da digitação para que o usuário já saiba o que é exigido e crie uma senha válida de primeira, sem passar pela frustração de uma falha.', 'Nota cheia: explica que mostrar as regras antes evita o erro e a frustração, permitindo acertar de primeira, com as próprias palavras. Metade: diz que as regras "devem aparecer antes", sem justificar. Zero: em branco, propõe mostrar só depois do erro ou copia sem adaptar.'),
      (v_atividade, 16, 1, 'Explique o que é tabular as falhas por categoria.', 0.2, 'Tabular as falhas é organizá-las em uma tabela por categoria (botões, rótulos, feedback, prevenção, diagnóstico), com a quantidade de falhas de cada uma, para enxergar onde o atrito se concentra.', 'Nota cheia: explica tabular como agrupar as falhas por categoria e contar ou comparar, com as próprias palavras. Metade: diz que é "anotar as falhas", sem a organização por categoria. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 16, 2, 'Explique por que as falhas críticas devem ser priorizadas antes das menores.', 0.4, 'Falhas críticas devem vir primeiro porque bloqueiam a conclusão da tarefa ou causam perda de dados, enquanto as menores incomodam, mas não impedem o usuário. Priorizar pelo impacto garante que o esforço da correção atinja o que mais atrapalha.', 'Nota cheia: justifica a prioridade das falhas críticas pelo impacto (bloqueio, perda ou desistência), com as próprias palavras. Metade: diz que as críticas são "mais importantes", sem justificar pelo impacto. Zero: em branco, defende corrigir as menores primeiro ou copia sem adaptar.'),
      (v_atividade, 16, 3, 'Explique o que a concentração de falhas em botões e rótulos indica sobre a tela.', 0.4, 'A concentração de falhas em botões e rótulos indica que a tela tem ambiguidade nas ações e falta de termos claros nos campos, que são justamente os pontos onde o usuário decide o que fazer. Por isso a correção deve começar por eles.', 'Nota cheia: interpreta a concentração como ambiguidade nos botões e falta de rótulos claros e liga isso à decisão do usuário, com as próprias palavras. Metade: diz que há muitos problemas nesses pontos, sem interpretar. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 17, 1, 'Liste as quatro etapas da auditoria na ordem em que devem ser feitas.', 0.2, 'As quatro etapas, na ordem, são: 1) identificar as queixas e os objetivos do usuário na jornada; 2) aplicar o checklist nos botões, termos e feedbacks; 3) tabular e priorizar as falhas mais críticas; 4) redesenhar a interface e testar com novos usuários.', 'Nota cheia: lista as quatro etapas na ordem correta (queixas e objetivos, checklist, tabulação e priorização, redesenho e teste). Metade: lista as quatro, mas com uma ou duas trocas de ordem. Zero: em branco, lista fora do conteúdo ou em ordem muito errada, ou copia sem adaptar.'),
      (v_atividade, 17, 2, 'Explique por que a primeira etapa é identificar as queixas e os objetivos do usuário.', 0.4, 'A primeira etapa é identificar as queixas e os objetivos do usuário porque a auditoria precisa partir do problema real de quem usa a tela. Sem saber o que a pessoa quer e onde reclama, o checklist seria aplicado sem foco.', 'Nota cheia: justifica a primeira etapa pela necessidade de partir das metas e queixas reais do usuário, com as próprias palavras. Metade: diz que é "o começo" ou "importante", sem justificar. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 17, 3, 'Explique por que o redesenho vem depois da tabulação das falhas.', 0.4, 'O redesenho vem depois da tabulação porque só depois de organizar e priorizar as falhas se sabe o que corrigir primeiro. Redesenhar antes seria mexer em tudo sem critério e sem medir o impacto.', 'Nota cheia: explica que o redesenho depende das falhas priorizadas, para corrigir primeiro o mais crítico e evitar mudanças sem critério, com as próprias palavras. Metade: diz que a tabulação "vem antes", sem justificar. Zero: em branco, inverte a ordem como correta ou copia sem adaptar.'),
      (v_atividade, 18, 1, 'Descreva a correção de rótulos e máscaras para o campo de data.', 0.2, 'Para o campo de data, deve-se adicionar um rótulo fixo acima do campo (por exemplo, "Data da consulta") e uma máscara automática no formato DD/MM/AAAA.', 'Nota cheia: propõe rótulo fixo visível acima do campo e máscara DD/MM/AAAA, com as próprias palavras. Metade: propõe só um dos dois. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 18, 2, 'Descreva a substituição de "Processar" por um botão de ação direta, com o texto que você escolheria.', 0.4, 'Substituir "Processar" por um botão de ação direta destacado, como "Confirmar Horário" ou "Confirmar Agendamento", que diz exatamente o que acontece ao clicar.', 'Nota cheia: propõe trocar "Processar" por botão destacado com texto de ação clara (ex.: "Confirmar Horário"), e justifica pela clareza. Metade: propõe botão melhor, sem justificar, ou com texto ainda vago. Zero: em branco, mantém "Processar" ou copia sem adaptar.'),
      (v_atividade, 18, 3, 'Descreva a tela de sucesso e explique como ela responde à dúvida do usuário.', 0.4, 'A tela de sucesso exibe um comprovante visual imediato com o número de protocolo e o resumo da data marcada. Assim o usuário vê que a consulta foi marcada e tem o dado para consultar depois, respondendo à dúvida "Marquei ou não?".', 'Nota cheia: descreve a tela de sucesso com comprovante imediato (protocolo e resumo da data) e explica que ela responde à dúvida de a consulta ter sido marcada. Metade: descreve a tela de sucesso, sem ligar à dúvida do usuário. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 19, 1, 'Explique por que a usabilidade não é um luxo opcional.', 0.2, 'A usabilidade não é luxo opcional nem detalhe cosmético: é uma métrica central de qualidade de software, porque define se o usuário consegue atingir a meta sem esforço indevido. Um sistema que não se usa bem perde valor, mesmo funcionando tecnicamente.', 'Nota cheia: explica que a usabilidade é métrica central de qualidade, e não detalhe ou luxo, ligando-a ao sucesso do usuário na meta, com as próprias palavras. Metade: diz que é "importante", sem ligar à qualidade do software. Zero: em branco, concorda que é detalhe cosmético ou copia sem adaptar.'),
      (v_atividade, 19, 2, 'Cite dois efeitos positivos de sistemas com alta usabilidade.', 0.4, 'Dois efeitos positivos são, por exemplo: reduzir chamados de suporte técnico e evitar erros críticos em hospitais e bancos (ou garantir que o cidadão exerça seus direitos pela web).', 'Nota cheia: cita dois efeitos positivos corretos, com as próprias palavras (ex.: menos chamados, menos erros críticos, acesso do cidadão). Metade: cita um efeito positivo correto. Zero: em branco, efeito que não é consequência da usabilidade ou copiado sem adaptar.'),
      (v_atividade, 19, 3, 'Proponha uma forma de considerar a usabilidade desde o início do projeto e justifique.', 0.4, 'Incluir a usabilidade desde o início pode ser feito com pesquisa de público e mapeamento da jornada antes do desenho, com testes de telas em protótipo com usuários reais. Assim os problemas aparecem cedo, quando custam menos para corrigir.', 'Nota cheia: propõe uma ação concreta desde o início (pesquisa, jornada, protótipo ou teste com usuários) e justifica pelo custo menor de correção antecipada, com as próprias palavras. Metade: propõe ação genérica ("testar com usuários") sem justificar. Zero: em branco, propõe tratar a usabilidade só no final ou copia sem adaptar.'),
      (v_atividade, 20, 1, 'Explique por que a falha de operação costuma ser do design e não do usuário.', 0.2, 'A falha de operação costuma ser do design porque decorre de ambiguidades no modelo mental, de convenções quebradas ou da falta de prevenção de erros pelo sistema, e não de falta de capacidade do usuário.', 'Nota cheia: explica que a falha vem de ambiguidade, convenção quebrada ou falta de prevenção no design, e não do usuário, com as próprias palavras. Metade: diz que "o design é que falha", sem explicar a causa. Zero: em branco, culpa o usuário ou copia sem adaptar.'),
      (v_atividade, 20, 2, 'Explique o que é o design centrado no usuário.', 0.4, 'O design centrado no usuário adapta o sistema às limitações humanas, para que o usuário não precise adivinhar regras não declaradas. Ele parte das necessidades, metas e contexto de quem usa, e testa com essas pessoas.', 'Nota cheia: define design centrado no usuário como adaptar o sistema às pessoas e às suas limitações, sem exigir adivinhação, com as próprias palavras. Metade: define de forma genérica ("pensar no usuário"), sem o aspecto de adaptação. Zero: em branco, fora do tema ou copiado.'),
      (v_atividade, 20, 3, 'Proponha uma ação concreta para a equipe, a partir da sua análise, e justifique.', 0.4, 'Uma ação concreta é, por exemplo, realizar uma auditoria de usabilidade da tela com queixas e corrigir primeiro as falhas críticas (como botões ambíguos e mensagens de erro), testando depois com usuários. Isso mostra à equipe que o problema é de design e tem solução.', 'Nota cheia: propõe uma ação concreta e aplicável à equipe (auditoria, checklist, correção priorizada, teste com usuários) e a justifica a partir da análise, com as próprias palavras. Metade: propõe ação genérica, sem ligar à análise. Zero: em branco, proposta que culpa o usuário ou copiada.');
end $$;
